186	// Forces the freshly created key file to exactly 0600: owner read/write, no
187	// execute bit, no group/other access. The mode given to open() is still
188	// reduced by the inherited process umask, which can strip owner read (umask
189	// 0400), owner write (umask 0200), or both (umask 0600); fchmod() is not
190	// affected by the umask. The result is verified with fstat() so a filesystem
191	// that silently keeps different permissions is treated as a failure instead
192	// of being reported as a success.
193	bool fixKeyFilePermissions(int fd, const std::string& path,
194	                           std::string& error) {
195	    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
196	        error = "cannot set key file permissions to 0600 on '" + path +
197	                "': " + errnoDescription(errno);
198	        return false;
199	    }
200	    struct stat info;
201	    if (::fstat(fd, &info) != 0) {
202	        error = "cannot verify key file permissions on '" + path +
203	                "': " + errnoDescription(errno);
204	        return false;
205	    }
206	    if ((info.st_mode & 0777) != (S_IRUSR | S_IWUSR)) {
207	        error = "cannot guarantee key file permissions 0600 on '" + path +
208	                "'";
209	        return false;
210	    }
211	    return true;
212	}
