214	// Creates a brand new file containing exactly keySize raw bytes. Any existing
215	// path (file, directory, symlink including a dangling one) is rejected. The
216	// file is created with mode 0600 and its permissions are then forced to
217	// exactly 0600 (the creation mode alone is still subject to the umask) before
218	// any key byte is written; at no point is the file accessible to group or
219	// other users.
220	//
221	// The outcome is reported entirely through KeySaveResult: an open() failure
222	// creates nothing (kNotCreated); a failure after creation closes the
223	// descriptor via the FdGuard and removes this run's file, reporting either
224	// kCleanedUp or, if the removal itself failed, kCleanupFailed with the
225	// removal reason in removalWarning so the caller can warn that an incomplete
226	// key file may remain. This function never writes to stdout or stderr.
227	KeySaveResult writeKeyFile(const std::string& path,
228	                           const unsigned char* key,
229	                           std::size_t keySize) {
230	    KeySaveResult result;
231	
232	    int fd = ::open(path.c_str(),
233	                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
234	                    S_IRUSR | S_IWUSR);
235	    if (fd == -1) {
236	        const int savedErrno = errno;
237	        // Pre-creation failure: nothing was created, so this must not enter
238	        // the "remove the new file" handling and an existing target's
239	        // content, permissions, and links are never touched.
240	        result.status = KeySaveStatus::kNotCreated;
241	        if (savedErrno == EEXIST || savedErrno == ELOOP) {
242	            result.error = "refusing to write, path already exists: " + path;
243	        } else {
244	            result.error = "cannot create key file '" + path + "': " +
245	                           errnoDescription(savedErrno);
246	        }
247	        return result;
248	    }
249	
250	    FdGuard guard(fd);
251	    result.status = KeySaveStatus::kCleanedUp;  // assumed until the save completes
252	    std::string error;
253	
254	    // If the permissions cannot be guaranteed, this run must not be reported
255	    // as a success even though the key was generated and the file was
256	    // created: skip the write and fall through to the cleanup below, before
257	    // any key byte reaches the file.
258	    if (fixKeyFilePermissions(fd, path, error)) {
259	        std::size_t totalWritten = 0;
260	        while (totalWritten < keySize) {
261	            ssize_t written =
262	                ::write(fd, key + totalWritten, keySize - totalWritten);
263	            if (written < 0) {
264	                if (errno == EINTR) {
265	                    continue;
266	                }
267	                error = "failed writing key file '" + path + "': " +
268	                        errnoDescription(errno);
269	                break;
270	            }
271	            if (written == 0) {
272	                error = "failed writing key file '" + path + "': short write";
273	                break;
274	            }
275	            totalWritten += static_cast<std::size_t>(written);
276	        }
277	
278	        if (totalWritten == keySize) {
279	            if (::fsync(fd) != 0) {
280	                error = "failed syncing key file '" + path + "': " +
281	                        errnoDescription(errno);
282	            } else if (guard.finish() != 0) {
283	                // The descriptor is closed by the kernel even when close
284	                // fails, but durability could not be confirmed: do not
285	                // report success.
286	                error = "failed closing key file '" + path + "': " +
287	                        errnoDescription(errno);
288	            } else {
289	                // The complete original key is written, synced, and closed;
290	                // 0600 was verified before the first byte.
291	                result.status = KeySaveStatus::kSaved;
292	                result.error.clear();
293	                return result;
294	            }
295	        }
296	    }
297	
298	    // Failure after creation. The descriptor opened by this run is closed
299	    // exactly once (guard.finish() above already disarmed it on the
300	    // close-failure path); removing the path cannot touch prior content
301	    // because O_EXCL guaranteed the file did not exist before open().
302	    guard.close();
303	    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
304	        // The original save failure remains the reported cause; this only
305	        // adds that the incomplete file could not be removed.
306	        result.status = KeySaveStatus::kCleanupFailed;
307	        result.removalWarning =
308	            "could not remove partial key file '" + path + "': " +
309	            errnoDescription(errno);
310	    }
311	    result.error = std::move(error);
312	    return result;
313	}
