389	// Outcome of writing the already-sealed envelope bytes to a brand new file.
390	// Mirrors KeySaveResult: the sealing/encryption step is finished before this
391	// runs, so the only failures here concern creating and saving the output.
392	struct EnvelopeSaveResult {
393	    KeySaveStatus status = KeySaveStatus::kNotCreated;
394	    std::string error;
395	    std::string removalWarning;
396	
397	    bool saved() const { return status == KeySaveStatus::kSaved; }
398	};
