674	int runEncrypt(int argc, char* argv[]) {
675	    std::string keyPath;
676	    std::string inputPath;
677	    std::string outputPath;
678	    bool haveKey = false;
679	    bool haveInput = false;
680	    bool haveOutput = false;
681	
682	    // All-or-nothing parse: validate the whole argument list and reject the
683	    // entire operation (exit 2) before any file is read or created.
684	    for (int i = 2; i < argc; ++i) {
685	        std::string_view arg(argv[i]);
686	        std::string_view option;
687	        std::string* target = nullptr;
688	        bool* seen = nullptr;
689	
690	        if (arg == "--key") {
691	            option = "--key";
692	            target = &keyPath;
693	            seen = &haveKey;
694	        } else if (arg == "--input") {
695	            option = "--input";
696	            target = &inputPath;
697	            seen = &haveInput;
698	        } else if (arg == "--output") {
699	            option = "--output";
700	            target = &outputPath;
701	            seen = &haveOutput;
702	        } else {
703	            std::cerr << "envelopefile: unsupported argument: '" << arg
704	                      << "'\n"
705	                      << kEncryptUsage;
706	            return 2;
707	        }
708	
709	        if (*seen) {
710	            std::cerr << "envelopefile: '" << option
711	                      << "' specified more than once\n"
712	                      << kEncryptUsage;
713	            return 2;
714	        }
715	        if (i + 1 >= argc) {
716	            std::cerr << "envelopefile: option '" << option
717	                      << "' requires a non-empty path\n"
718	                      << kEncryptUsage;
719	            return 2;
720	        }
721	        *target = argv[++i];
722	        if (target->empty()) {
723	            std::cerr << "envelopefile: option '" << option
724	                      << "' requires a non-empty path\n"
725	                      << kEncryptUsage;
726	            return 2;
727	        }
728	        *seen = true;
729	    }
730	
731	    if (!haveKey || !haveInput || !haveOutput) {
732	        if (!haveKey) {
733	            std::cerr << "envelopefile: missing required option '--key'\n"
734	                      << kEncryptUsage;
735	        } else if (!haveInput) {
736	            std::cerr << "envelopefile: missing required option '--input'\n"
737	                      << kEncryptUsage;
738	        } else {
739	            std::cerr << "envelopefile: missing required option '--output'\n"
740	                      << kEncryptUsage;
741	        }
742	        return 2;
743	    }
744	
745	    // Read the exact 32-byte raw key. This buffer is wiped on every exit
746	    // path (success or failure), so the key never survives the operation in
747	    // memory and never reaches stdout/stderr.
748	    SecureBuffer key(kKeyBytes);
749	    {
750	        std::string error;
751	        if (!readKeyFile(keyPath, key, error)) {
752	            std::cerr << "envelopefile: " << error << '\n';
753	            return 1;
754	        }
755	    }
756	
757	    // Read the input as raw bytes (no conversion; empty input is allowed).
758	    std::vector<unsigned char> plaintext;
759	    {
760	        std::string error;
761	        if (!readAllBytes(inputPath, plaintext, error, "input file")) {
762	            std::cerr << "envelopefile: " << error << '\n';
763	            return 1;
764	        }
765	    }
766	
767	    // Seal with a fresh random nonce and an authenticated header.
768	    std::vector<unsigned char> envelope;
769	    {
770	        std::string error;
771	        if (!sealEnvelope(key.data(), plaintext, envelope, error)) {
772	            std::cerr << "envelopefile: " << error << '\n';
773	            return 1;
774	        }
775	    }
776	
